%% 04_Wireless_Performance.m
% =========================================================================
% Reconfigurable Intelligent Surface (RIS) Research Project
% Script 4: Wireless Communication Performance Simulation
% 
% Description:
%   Evaluates the wireless communication performance using a realistic 
%   indoor log-distance propagation model with shadow fading and wall 
%   attenuation. Includes a physically consistent RIS gain model utilizing 
%   HFSS reflection coefficients.
% =========================================================================

clear; close all; clc;
tic;

%% ========================================================================
% SECTION 1 - INITIALIZATION
% =========================================================================
disp('==========================================================='); %[output:16387cd3]
disp('   Wireless Performance Simulation Started'); %[output:08fbecd3]
disp('==========================================================='); %[output:350e2d5b]

% Define Directory Paths
dataDir = fullfile(pwd, 'Data');
figDir  = fullfile(pwd, 'Figures');
resDir  = fullfile(pwd, 'Results');

% Create directories if they do not exist
if ~exist(dataDir, 'dir'), mkdir(dataDir); end
if ~exist(figDir, 'dir'), mkdir(figDir); end
if ~exist(resDir, 'dir'), mkdir(resDir); end

% Define Required Files
reqFiles = {fullfile(dataDir, 'HFSS_Parameters.mat'), ...
            fullfile(dataDir, 'RIS_Array.mat'), ...
            fullfile(dataDir, 'Phase_Data.mat')};

% Verify all files exist
for i = 1:length(reqFiles)
    if ~isfile(reqFiles{i})
        error('Required file "%s" not found. Please run previous scripts.', reqFiles{i});
    end
end

% Load Data
disp('Loading required datasets from Data/ folder...'); %[output:415ebe37]
load(reqFiles{1}); % Loads HFSS Parameters (GammaON, GammaOFF, f, etc.)
load(reqFiles{2}); % Loads RIS Geometry
load(reqFiles{3}); % Loads PhaseData (ControlMatrix, Tx, Rx, etc.)
disp(' -> All Data Loaded Successfully.'); %[output:1d807cc5]

%% ========================================================================
% SECTION 2 - USER SETTINGS
% =========================================================================
% System Parameters
Freq_MHz = f / 1e6;       % Operating Frequency in MHz
Pt_dBm   = 20;            % Transmit Power in dBm
BW_Hz    = 20e6;          % Bandwidth (20 MHz)
NF_dB    = 6;             % Receiver Noise Figure in dB
T_K      = 290;           % System Temperature in Kelvin

Gt_dBi = 2;               % Tx Antenna Gain (dBi)
Gr_dBi = 2;               % Rx Antenna Gain (dBi)

% Environment Setup
Tx_pos  = [1, 5];         % Wi-Fi Router position (x, y) in meters
RIS_pos = [5, 5];         % RIS position (x, y) in meters

% Comparison Mode Settings ("Surface" or "Array")
ComparisonMode = "Array"; 
CompareArrays  = [0 2 5 9 16 ]; % Used if Mode == "Array"

disp([' -> Comparison Mode Active: ', char(ComparisonMode)]); %[output:9e9945ae]

%% ========================================================================
% SECTION 3 - PROPAGATION MODEL (LOG-DISTANCE + SHADOWING + WALLS)
% =========================================================================
disp('Generating Indoor Propagation Environment...'); %[output:212f8ae7]

% Create a 10 m x 10 m indoor receiver grid
grid_res = 0.1; 
x_vec = 0:grid_res:10;
y_vec = 0:grid_res:10;
[X_grid, Y_grid] = meshgrid(x_vec, y_vec);

% Calculate distances (prevent log(0) with max(..., 1e-4))
d_dir = max(1e-4, sqrt((X_grid - Tx_pos(1)).^2 + (Y_grid - Tx_pos(2)).^2));
d_1   = max(1e-4, norm(RIS_pos - Tx_pos)); % Tx to RIS
d_2   = max(1e-4, sqrt((X_grid - RIS_pos(1)).^2 + (Y_grid - RIS_pos(2)).^2)); % RIS to Rx

% Log-Distance Path Loss Parameters
lambda = 300 / Freq_MHz; % Wavelength in meters
PL_d0 = 20*log10(4*pi*1 / lambda); % Reference path loss at d0 = 1m (~40 dB)

PLE_LoS  = 2.0; % Path Loss Exponent for unobstructed paths
PLE_NLoS = 3.2; % Path Loss Exponent for obstructed direct path

% Shadow Fading
rng(42); % Fixed seed for reproducibility between runs
Shadow_Std = 3.5; % Shadow fading standard deviation in dB
ShadowFadingMatrix = Shadow_Std * randn(size(X_grid));

% Wall Attenuation Model
% Assume a partition wall at X = 3.5m blocking the direct Wi-Fi path
Wall_X = 3.5;
Wall_Loss_dB = 12; 
Wall_Mask = (X_grid > Wall_X); 

% 1. Direct Path Loss (NLoS, severely attenuated by wall)
PL_Direct = PL_d0 + 10 * PLE_NLoS * log10(d_dir) + (Wall_Mask * Wall_Loss_dB) + ShadowFadingMatrix;

% 2. Cascaded RIS Path Loss (Assumed LoS to overcome the wall blockage)
% Physical cascading formula: PL_Cascaded = PL_Tx_RIS + PL_RIS_Rx
PL_Cascaded = (PL_d0 + 10 * PLE_LoS * log10(d_1)) + ...
              (PL_d0 + 10 * PLE_LoS * log10(d_2)) + ShadowFadingMatrix;

%% ========================================================================
% SECTION 4 - RIS GAIN MODEL (PHYSICALLY CONSISTENT HFSS MODEL)
% =========================================================================
% Extract base ON/OFF ratios from Script 3 quantization
ControlMat = PhaseData.ControlMatrix;
N_total_base = numel(ControlMat);
N_on_base = sum(ControlMat(:));
N_off_base = N_total_base - N_on_base;

Ratio_ON = N_on_base / N_total_base;
Ratio_OFF = N_off_base / N_total_base;

BaseElementGain = 5; % Typical patch element gain (dBi)

% Define configurations
if strcmpi(ComparisonMode, "Surface")
    Configs = [0, 1, 2, 3];
    ConfLabels = {'No RIS', 'Single RIS', 'Double RIS', 'Triple RIS'};
elseif strcmpi(ComparisonMode, "Array")
    Configs = CompareArrays;
    ConfLabels = cell(1, length(Configs));
    for i = 1:length(Configs)
        if Configs(i) == 0
            ConfLabels{i} = 'No RIS';
        else
            ConfLabels{i} = sprintf('%dx%d RIS', Configs(i), Configs(i));
        end
    end
else
    error('ComparisonMode must be "Surface" or "Array".');
end

num_configs = length(Configs);

%% ========================================================================
% SECTION 5, 6 & 7 - POWER, RSSI, AND SNR
% =========================================================================
disp('Computing RSSI and SNR metrics...'); %[output:00174a9d]

% Thermal Noise Calculation
k_Boltzmann = 1.380649e-23;
NoisePower_W = k_Boltzmann * T_K * BW_Hz;
NoisePower_dBm = 10*log10(NoisePower_W) + 30 + NF_dB;

% Preallocate memory
RSSI_Maps = cell(1, num_configs);
SNR_Maps  = cell(1, num_configs);
PL_Maps   = cell(1, num_configs);

Avg_RSSI = zeros(num_configs, 1);
Max_RSSI = zeros(num_configs, 1);
Avg_SNR  = zeros(num_configs, 1);
Avg_PL   = zeros(num_configs, 1);
Gain_Val = zeros(num_configs, 1);

for i = 1:num_configs
    cfg = Configs(i);
    
    if cfg == 0
        % Baseline: Direct path only
        Pr_dBm = Pt_dBm + Gt_dBi + Gr_dBi - PL_Direct;
        Eff_PL = PL_Direct;
        Gain_Val(i) = 0;
    else
        % Scale total elements
        if strcmpi(ComparisonMode, "Surface")
            N_elements = cfg * N_total_base;
        else
            N_elements = cfg^2;
        end
        
        % Rigorous Gain Calculation
        % Superposition of reflected fields based on exact HFSS coefficients
        Gamma_Avg = abs(Ratio_ON * GammaON + Ratio_OFF * GammaOFF);
        
        % Power array gain = G_element + 20*log10(N) + 20*log10(|Gamma_avg|)
        % Using max(Gamma_Avg, 1e-6) to prevent log10(0) mathematically
        RIS_Gain = BaseElementGain + 20*log10(N_elements) + 20*log10(max(Gamma_Avg, 1e-6));
        Gain_Val(i) = RIS_Gain;
        
        % Power via RIS path
        Pr_RIS_dBm = Pt_dBm + Gt_dBi + Gr_dBi - PL_Cascaded + RIS_Gain;
        
        % Coherent combination assumed in fading environment (power sum)
        Pr_Linear = 10.^(Pr_dBm / 10) + 10.^(Pr_RIS_dBm / 10);
        Pr_dBm = 10*log10(Pr_Linear);
        
        % Effective Path Loss
        Eff_PL = Pt_dBm + Gt_dBi + Gr_dBi - Pr_dBm;
    end
    
    RSSI_Maps{i} = Pr_dBm;
    SNR_Maps{i}  = Pr_dBm - NoisePower_dBm;
    PL_Maps{i}   = Eff_PL;
    
    Avg_RSSI(i) = mean(RSSI_Maps{i}(:));
    Max_RSSI(i) = max(RSSI_Maps{i}(:));
    Avg_SNR(i)  = mean(SNR_Maps{i}(:));
    Avg_PL(i)   = mean(PL_Maps{i}(:));
end

%% ========================================================================
% SECTION 8 - PERFORMANCE TABLE
% =========================================================================
PerformanceTable = table(ConfLabels', Avg_RSSI, Max_RSSI, Avg_SNR, Avg_PL, Gain_Val, ...
    'VariableNames', {'Configuration', 'Average_RSSI_dBm', 'Maximum_RSSI_dBm', ...
                      'Average_SNR_dB', 'Average_PathLoss_dB', 'RIS_Gain_dBi'});

disp(' '); %[output:5ddbdee2]
disp('--- Performance Evaluation Table ---'); %[output:31007644]
disp(PerformanceTable); %[output:8282646b]

%% ========================================================================
% SECTION 9, 10, 11 - 1D PLOTS (Slice at Y = 5)
% =========================================================================
% Plot along X-axis directly crossing the Tx and RIS line
y_idx = find(abs(y_vec - 5) < 1e-3, 1);
dist_x = x_vec; 

fontName = 'Times New Roman';
fontSize = 12;
colors = lines(num_configs);
lineStyles = {'-', '--', ':', '-.', '-', '--', ':'};

disp('Generating publication figures...'); %[output:32a9c531]

% --- FIGURE 1: RSSI vs Distance ---
fig1 = figure('Name', 'RSSI vs Distance', 'Color', 'w', 'Position', [100 100 700 500]); %[output:5aa671e7]
hold on; grid on; %[output:5aa671e7]
for i = 1:num_configs
    plot(dist_x, RSSI_Maps{i}(y_idx, :), 'LineStyle', lineStyles{mod(i-1,length(lineStyles))+1}, ... %[output:5aa671e7]
        'Color', colors(i,:), 'LineWidth', 2); %[output:5aa671e7]
end
xline(Wall_X, 'k-', 'Wall (Blockage)', 'LineWidth', 2, 'LabelVerticalAlignment', 'top'); %[output:5aa671e7]
xline(RIS_pos(1), 'r:', 'RIS Location', 'LineWidth', 1.5, 'LabelVerticalAlignment', 'bottom'); %[output:5aa671e7]
title('RSSI vs Distance with Shadow Fading (Y = 5m Slice)', 'FontName', fontName, 'FontSize', fontSize+2); %[output:5aa671e7]
xlabel('Room X-Coordinate (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:5aa671e7]
ylabel('RSSI (dBm)', 'FontName', fontName, 'FontSize', fontSize); %[output:5aa671e7]
legend(ConfLabels, 'Location', 'southwest'); %[output:5aa671e7]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:5aa671e7]

% --- FIGURE 2: SNR vs Distance ---
fig2 = figure('Name', 'SNR vs Distance', 'Color', 'w', 'Position', [150 150 700 500]); %[output:68921415]
hold on; grid on; %[output:68921415]
for i = 1:num_configs
    plot(dist_x, SNR_Maps{i}(y_idx, :), 'LineStyle', lineStyles{mod(i-1,length(lineStyles))+1}, ... %[output:68921415]
        'Color', colors(i,:), 'LineWidth', 2); %[output:68921415]
end
xline(Wall_X, 'k-', 'LineWidth', 2); %[output:68921415]
xline(RIS_pos(1), 'r:', 'LineWidth', 1.5); %[output:68921415]
title('SNR vs Distance (Y = 5m Slice)', 'FontName', fontName, 'FontSize', fontSize+2); %[output:68921415]
xlabel('Room X-Coordinate (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:68921415]
ylabel('SNR (dB)', 'FontName', fontName, 'FontSize', fontSize); %[output:68921415]
legend(ConfLabels, 'Location', 'southwest'); %[output:68921415]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:68921415]

% --- FIGURE 3: PATH LOSS vs Distance ---
fig3 = figure('Name', 'Path Loss vs Distance', 'Color', 'w', 'Position', [200 200 700 500]); %[output:980ed332]
hold on; grid on; %[output:980ed332]
for i = 1:num_configs
    plot(dist_x, PL_Maps{i}(y_idx, :), 'LineStyle', lineStyles{mod(i-1,length(lineStyles))+1}, ... %[output:980ed332]
        'Color', colors(i,:), 'LineWidth', 2); %[output:980ed332]
end
xline(Wall_X, 'k-', 'LineWidth', 2); %[output:980ed332]
xline(RIS_pos(1), 'r:', 'LineWidth', 1.5); %[output:980ed332]
title('Effective Path Loss vs Distance', 'FontName', fontName, 'FontSize', fontSize+2); %[output:980ed332]
xlabel('Room X-Coordinate (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:980ed332]
ylabel('Path Loss (dB)', 'FontName', fontName, 'FontSize', fontSize); %[output:980ed332]
legend(ConfLabels, 'Location', 'northwest'); %[output:980ed332]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:980ed332]


%% ========================================================================
% SECTION 13 - FIGURE 5: PERFORMANCE COMPARISON
% =========================================================================
fig5 = figure('Name', 'Performance Comparison', 'Color', 'w', 'Position', [300 300 900 500]); %[output:16593e83]

% Normalize data for grouped bar chart clarity
norm_RSSI = Avg_RSSI - min(Avg_RSSI) + 1; % Shift to positive for bar chart
plotData = [norm_RSSI, Avg_SNR];

b = bar(plotData, 'grouped'); %[output:16593e83]
set(gca, 'XTickLabel', ConfLabels, 'FontName', fontName, 'FontSize', fontSize); %[output:16593e83]
ylabel('Value (Units vary)', 'FontName', fontName, 'FontSize', fontSize); %[output:16593e83]
title('Wireless Performance Comparison', 'FontName', fontName, 'FontSize', fontSize+2); %[output:16593e83]
legend('Avg RSSI (Relative)', 'Avg SNR (dB)', 'Location', 'northwest'); %[output:16593e83]
grid on; %[output:16593e83]

%% ========================================================================
% SECTION 14 - SAVE RESULTS
% =========================================================================
disp('Saving data structures...'); %[output:15eceb47]

WirelessPerformance.RoomX = x_vec;
WirelessPerformance.RoomY = y_vec;
WirelessPerformance.Configurations = ConfLabels;
WirelessPerformance.RSSI = RSSI_Maps;
WirelessPerformance.SNR = SNR_Maps;
WirelessPerformance.PathLoss = PL_Maps;
WirelessPerformance.PerformanceTable = PerformanceTable;

SimulationParameters.Freq = Freq_MHz;
SimulationParameters.Pt = Pt_dBm;
SimulationParameters.NoisePower = NoisePower_dBm;
SimulationParameters.Mode = ComparisonMode;
WirelessPerformance.SimulationParameters = SimulationParameters;

%% ========================================================================
% SECTION 15 - EXPORT
% =========================================================================
% Save MAT file to Data folder
save(fullfile(dataDir, 'WirelessPerformance.png'), 'WirelessPerformance');

% Export Table to Results folder
writetable(PerformanceTable, fullfile(resDir, 'Performance_Table.csv'));

% Export Figures to Figures folder
disp('Exporting figures to Figures/ directory...'); %[output:915345b5]
figs = [fig1, fig2, fig3,fig5];
fnames = {'WP_Figure1_RSSI', 'WP_Figure2_SNR', 'WP_Figure3_PathLoss', 'WP_Figure4_RSSI_Heatmap', 'WP_Figure5_Comparison'};

for i = 1:length(figs) %[output:group:44d43bc3]
    baseStr = fullfile(figDir, fnames{i});
    exportgraphics(figs(i), [baseStr, '.png'], 'Resolution', 300); %[output:5aa671e7] %[output:68921415] %[output:980ed332] %[output:16593e83]
    exportgraphics(figs(i), [baseStr, '.pdf'], 'ContentType', 'vector');
    savefig(figs(i), [baseStr, '.fig']);
end %[output:group:44d43bc3]
disp(' -> Exports completed successfully.'); %[output:090d4dc7]

%% ========================================================================
% SECTION 16 - COMMAND WINDOW
% =========================================================================
% Find Best Configuration based on Average RSSI
[~, best_idx] = max(Avg_RSSI);

simTime = toc;

disp(' '); %[output:3a530726]
disp('========================================='); %[output:47b9d10d]
disp('      WIRELESS PERFORMANCE SUMMARY'); %[output:6ace7469]
disp('========================================='); %[output:6ae92c16]
fprintf('Frequency           : %.2f GHz\n', Freq_MHz / 1000); %[output:35bebc50]
fprintf('Comparison Mode     : %s\n\n', ComparisonMode); %[output:0b21aa58]

fprintf('%-15s | %-12s | %-12s | %-10s | %-10s\n', ... %[output:group:25a54dfa] %[output:2bbbb278]
    'Configuration', 'Avg RSSI', 'Max RSSI', 'Avg SNR', 'Avg PL'); %[output:group:25a54dfa] %[output:2bbbb278]
fprintf('----------------------------------------------------------------------\n'); %[output:1e053060]
for i = 1:num_configs %[output:group:26725314]
    fprintf('%-15s | %-8.2f dBm | %-8.2f dBm | %-7.2f dB | %-7.2f dB\n', ... %[output:093ab9d6]
        ConfLabels{i}, Avg_RSSI(i), Max_RSSI(i), Avg_SNR(i), Avg_PL(i)); %[output:093ab9d6]
end %[output:group:26725314]
disp('----------------------------------------------------------------------'); %[output:5f868f68]
fprintf('Best Configuration  : %s\n', ConfLabels{best_idx}); %[output:014d4e59]
fprintf('Simulation Time     : %.2f sec\n', simTime); %[output:98e7141b]
disp('========================================='); %[output:0cf4441b]

